 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    # Motif detection: compact non-background patch containing at least two colors,
    # copied at each isolated marker color. Demo 3 has a single 5x5 pattern and
    # marker 0; repeat pattern at markers. Adapt coordinates by its bounding box.
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg]
    # Identify the dense colored motif as the largest local region of non-bg cells.
    # Use the motif shape known from examples as the rectangle with the greatest
    # number of colored pixels, excluding isolated same-color anchors.
    best=None
    for r0 in range(h):
      for c0 in range(w):
       for hh in range(2,min(8,h-r0)+1):
        for ww in range(2,min(8,w-c0)+1):
         n=sum(grid[r][c]!=bg for r in range(r0,r0+hh) for c in range(c0,c0+ww))
         if n>=8 and (best is None or n>best[0]): best=(n,r0,c0,hh,ww)
    if not best:return [row[:] for row in grid]
    _,r0,c0,hh,ww=best
    motif=[[grid[r0+i][c0+j] for j in range(ww)] for i in range(hh)]
    g=[row[:] for row in grid]
    # Anchors are isolated non-background singletons, copy motif with its top-left
    # aligned to the anchor, preserving the original motif.
    anchors=[]
    for r,c in cells:
      if not (r0<=r<r0+hh and c0<=c<c0+ww):
       if sum(1 for rr,cc in cells if abs(rr-r)+abs(cc-c)<=1)==1: anchors.append((r,c))
    for ar,ac in anchors:
      for i in range(hh):
       for j in range(ww):
        rr,cc=ar+i,ac+j
        if rr<h and cc<w:g[rr][cc]=motif[i][j]
    return g
